(OUT/'catalog.json').write_text(json.dumps([{'id':id,'title':' '.join(lines),'description':sub,'cta':themes[id][2],'colors':themes[id][:2]} for id,lines,sub,*_ in data],ensure_ascii=False,indent=2)+'\n')
